// Data written before the backend seat got its stable `backend` id carries its former id, which was the lowercased
// default label. It is derived, never spelled, and only read: `canonicalMemberId` maps it to `backend` wherever a stored
// or user-supplied member id enters, and every write uses `backend`.
export const LEGACY_BACKEND_ID = BACKEND_DEFAULT_LABEL.toLowerCase()

export function canonicalMemberId(id: string): string
export function canonicalMemberId(id: string | undefined): string | undefined
export function canonicalMemberId(id: string | undefined) {
  return id === LEGACY_BACKEND_ID ? "backend" : id
}

export const nativeProfiles: Readonly<Record<string, NativeProfile>> = Object.freeze({
  ...baseProfiles,
  ...Object.fromEntries(Object.values(Seats.all).flatMap((seat) => {
    const profile = seatProfile(seat)
    return [[seat.id, profile], ...(seat.profileKey && seat.profileKey !== seat.id ? [[seat.profileKey, profile]] : [])]
  })),
})

// Seat-specific grants extend the unchanged base. The root edit deny is worktree-relative and added by Agent.
function seatProfile(seat: Seat): NativeProfile {
  const root = SeatSkillRoot.roots[seat.id]
  if (seat.skills.length > 0 && !root) throw new Error(`Missing native seat skill root: ${seat.id}`)
  return Object.freeze({
    ...baseProfiles[seat.profile],
    ...Object.fromEntries((seat.mcp ?? []).map((server) => [`${server}_*`, "allow" as const])),
    ...(seat.atlasMemory ? { atlas_context: "allow" as const, atlas_memory_recall: "allow" as const, atlas_memory_emit: "allow" as const } : {}),
    ...(seat.id === "archie" ? {
      atlas_context: "allow" as const,
      archie_draft_workflow: "allow" as const,
      maestro_arsenal_catalog: "allow" as const,
      ...Object.fromEntries(["maestro_arsenal_describe", "maestro_arsenal_execute"].map((name) => [name, Object.freeze({
        "*": "deny" as const,
        ...Object.fromEntries(UpstreamArsenal.UPSTREAM_AUTHORING_OPERATIONS.map((operation) => [operation, "allow" as const])),
      })])),
    } : {}),
    ...(seat.skills.length > 0 ? {
      // A root opens its whole tree: every node below it is named `<root>-<path>`.
      skill: Object.freeze({
        "*": "deny" as const,
        ...Object.fromEntries(seat.skills.flatMap((name) => [[name, "allow" as const], [`${name}-*`, "allow" as const]])),
      }),
      external_directory: Object.freeze({
        ...(seat.profile === "review" ? baseProfiles.review.external_directory
          : seat.profile === "discovery" ? baseProfiles.discovery.external_directory
          : seat.profile === "direct" ? baseProfiles.direct.external_directory : { "*": "deny" as const }),
        [path.join(root, "*")]: "allow" as const,
        ...(SeatSkillRoot.shared && seat.skills.some((skill) => skill.startsWith("team-"))
          ? { [path.join(SeatSkillRoot.shared, "*")]: "allow" as const }
          : {}),
      }),
    } : {}),
  })
}

export function envRead<Action extends "ask" | "deny">(action: Action) {
  return Object.freeze({ "*": "allow", "*.env": action, "*.env.*": action, "*.env.example": "allow" } as const)
}

