/** A roster profile (`{ action: effect | { resource: effect } }`) as V2 rules, in the profile's order. */
export function floor(
  profile: Readonly<Record<string, RuleEffect | Readonly<Record<string, RuleEffect>>>> | undefined,
) {
  return Object.entries(profile ?? {}).flatMap(([action, value]) =>
    typeof value === "string"
      ? [{ action, resource: "*", effect: value }]
      : Object.entries(value).map(([resource, effect]) => ({ action, resource, effect })),
  )
}

/** The rules denying an agent the tools it may not use, other seats' skills and, unless it is Maestro, the playbooks. */
export function visibility(id: string): PermissionV2.Ruleset {
  return [
    ...owners
      .filter((owner) => !owner.agents.includes(id))
      .flatMap((owner) => owner.tools.map((tool) => ({ action: tool, resource: "*", effect: "deny" as const }))),
    ...MaestroSkillSourcesV2.foreign(id),
    ...(id === AgentV2.defaultID ? [] : MaestroSkillSourcesV2.denied),
  ]
}

export const check = Effect.fn("CallerGateV2.check")(function* (
  seats: MaestroSeats.Interface,
  profiles: typeof nativeProfiles,
  caller: string,
  target: string,
) {
  if (!seats.has(caller)) return
  // The profile's own order, as `MaestroSeatsV2.floor` reads it; importing that here would make `seats.ts` a cycle.
  const rules = Object.entries(profiles[caller] ?? {}).flatMap(([action, value]) =>
    typeof value === "string"
      ? [{ action, resource: "*", effect: value }]
      : Object.entries(value).map(([resource, effect]) => ({ action, resource, effect })),
  )
  if (PermissionV2.evaluate("task", target, rules).effect !== "deny") return
  return yield* new ToolFailure({ message: `Task denied: ${caller} may not start ${target}` })
})

