const create = (request: Request, agent?: AgentV2.ID, explicit = false) =>
  EffectRuntime.uninterruptible(
    EffectRuntime.gen(function* () {
      const deferred = yield* Deferred.make<void, DeclinedError | CorrectedError>()
      const item = { request, agent, deferred, explicit }
      if (pending.has(request.id)) return yield* EffectRuntime.die(`Duplicate pending permission ID: ${request.id}`)
      pending.set(request.id, item)
      yield* events
        .publish(Event.Asked, request)

// The roster loads lazily (see `seats.ts`); where it cannot load no agent is a seat, so no profile is read.
const rosterModule = yield* Effect.tryPromise(() => import("../roster")).pipe(Effect.option)
const profiles = rosterModule._tag === "Some" ? rosterModule.value.nativeProfiles : {}
const canonical = (id: string): string => (rosterModule._tag === "Some" ? rosterModule.value.canonicalMemberId(id) : id)
const services = { db: database.db, store, events, canonical, allowances, location, atlas: { config, git, fs, skills } }
const seatOf = (id: string) => (seats.has(canonical(id)) ? Seats.all[canonical(id)] : undefined)

// A child's first provider turn: its reservation is revalidated or consumed, and a strict-resume seat binds its task.
function firstTurn(session: SessionSchema.Info) {
  return Effect.gen(function* () {
    const dispatch = session.id.startsWith(GovernanceDispatchV2.CHILD_PREFIX)
    const governed = session.id.startsWith(GovernanceReservationV2.CHILD_PREFIX)
    if (dispatch) yield* revalidateDispatch(session.id)
    if (governed) yield* GovernanceReservationV2.consume(services, session.id)
    const member = canonical(session.agent ?? AgentV2.defaultID)
    if (!seatOf(member)?.strictResume && !(yield* WorkflowGateV2.bound(database, session.id))) return
    const authority = yield* SessionAuthority.make(store.get)(session.id, session.projectID).pipe(
      Effect.mapError((error) => new ToolFailure({ message: `Task binding denied: ${error.reason}` })),
    )
    yield* LogicalTaskV2.ensure(services, {
      executionSessionID: session.id,
      authoritySessionID: authority.rootID,
      projectID: session.projectID,
      memberID: member,
      ...LogicalTaskV2.origin(dispatch || governed ? session.id : undefined, governed),
    })
  })
}

/**
 * Bind the execution Session to its logical task, once. Re-binding with the same fields returns the stored binding;
 * any different binding on the same Session fails `task-binding-mismatch`. Without `taskId` the host generates one.
 */
export const ensure = Effect.fn("LogicalTaskV2.ensure")(function* (
  services: Services,
  input: {
    executionSessionID: string
    authoritySessionID: string
    projectID: string
    memberID: string
    source: Source
    taskId?: string
  },
) {
  if (input.source === "user" && !USER_TASK_ID.test(input.taskId ?? "")) return yield* denied("binding", "task-id-invalid")
  const existing = yield* readStored(services, input.executionSessionID)
  if (existing) return yield* reconcile(services, existing, input)
  const authority = yield* SessionAuthority.make(services.store.get)(input.executionSessionID, input.projectID).pipe(
    Effect.mapError((error) => denied("binding", error.reason)),
  )
  if (input.authoritySessionID !== authority.rootID) return yield* denied("binding", "task-authority-mismatch")
  const binding = {
    taskId: input.taskId ?? `tsk_${ascending()}`,
    projectID: input.projectID,
    memberID: input.memberID,
    executionSessionID: input.executionSessionID,
    authoritySessionID: authority.rootID,
    source: input.source,
  }
  return yield* services.events.publish(MaestroEvent.Task.Bound, binding, { id: eventID(input.executionSessionID) }).pipe(
    Effect.map((event) => event.data),
    // A concurrent bind of the same Session won the insert: the stored binding decides.
    Effect.catchCause((cause) =>
      Effect.gen(function* () {
        const stored = yield* readStored(services, input.executionSessionID)
        if (!stored) return yield* Effect.failCause(cause)
        return yield* reconcile(services, stored, input)
      }),
    ),
  )
})
